styl:
.white-bg.b-system-text-84 {  background:#fff  }
.b-system-text-84 .title {  color:#2473d7;font-size:24px;font-weight:500;line-height:32px;padding-top:30px;padding-bottom:25px  }
@media screen and (max-width:600px) {
  .b-system-text-84 .title {  padding-left:20px!important;padding-right:20px!important  }
}
.b-system-text-84 .text {  color:#5b6e88;font-size:16px;font-weight:400;line-height:24px;padding-bottom:20px  }
@media screen and (max-width:600px) {
  .b-system-text-84 .text {  padding-left:20px!important;padding-right:20px!important  }
}
.b-system-text-84 .text a {  color:#2473d7;text-decoration:underline  }
.b-system-text-84 .text.bold {  font-weight:700  }
.b-system-text-84 .list {  display:list-item;padding-left:20px;list-style:decimal;list-style-position:inside;padding-bottom:10px  }
